export function createDebouncer(waitMs) {
  const timers = new Map()

  function schedule(k, callback) {
    cancel(k)

    const timer = setTimeout(() => {
      timers.delete(k)
      void Promise.resolve()
        .then(callback)
        .catch(() => {})
    }, waitMs)

    timers.set(k, timer)
  }

  function cancel(k) {
    const timer = timers.get(k)
    if (!timer) return false

    clearTimeout(timer)
    timers.delete(k)
    return true
  }

  function cancelAll() {
    for (const timer of timers.values()) {
      clearTimeout(timer)
    }
    timers.clear()
  }

  return { schedule, cancel, cancelAll }
}
